import { test } from "node:test";
import assert from "node:assert/strict";
import { setImmediate as tick } from "node:timers/promises";
import { AVAILABILITY_TTL_MS, SeatInventory, SoldOutError, type EventRow, type EventStore } from "../src/tickets/inventory.ts";
import { holdSeats } from "../src/tickets/holds.ts";

// The store reads a snapshot of the row, then (optionally) stalls before returning it,
// like a query whose result is slow to come back over the network.
function memoryStore(rows: EventRow[]) {
    const byId = new Map(rows.map((r) => [r.eventId, structuredClone(r)]));
    let stall: Promise<void> | undefined;
    const store: EventStore & { loads: number; stallNextLoad(): () => void } = {
        loads: 0,
        stallNextLoad() {
            let resume!: () => void;
            stall = new Promise<void>((r) => (resume = r));
            return resume;
        },
        async load(id) {
            this.loads++;
            const row = byId.get(id);
            const snapshot = row ? structuredClone(row) : null;
            const wait = stall;
            stall = undefined;
            await (wait ?? tick());
            return snapshot;
        },
        async adjust(id, section, delta) {
            await tick();
            const row = byId.get(id);
            if (!row || !(section in row.seatsLeft)) throw new Error(`no ${section} at ${id}`);
            if (row.seatsLeft[section] + delta < 0) throw new SoldOutError(id, section);
            row.seatsLeft[section] += delta;
            return ++row.version;
        },
    };
    return store;
}

function setup() {
    let now = Date.parse("2026-11-19T10:00:00Z");
    const store = memoryStore([{ eventId: "tour-oslo", version: 1, seatsLeft: { floor: 4, balcony: 0 } }]);
    const inventory = new SeatInventory(store, () => now);
    return { store, inventory, advance: (ms: number) => (now += ms) };
}

test("availability is read from the store once, then from the cache", async () => {
    const { store, inventory } = setup();
    assert.deepEqual(await inventory.availability("tour-oslo"), { floor: 4, balcony: 0 });
    await inventory.availability("tour-oslo");
    await holdSeats(inventory, "tour-oslo", "balcony", 2);
    assert.equal(store.loads, 1);
});

test("a reservation shows up in availability straight away", async () => {
    const { inventory } = setup();
    await inventory.availability("tour-oslo");
    assert.deepEqual(await holdSeats(inventory, "tour-oslo", "floor", 3), { ok: true, section: "floor", qty: 3 });
    assert.equal((await inventory.availability("tour-oslo")).floor, 1);
});

test("a page load that started before a reservation doesn't put the old count back in the cache", async () => {
    const { store, inventory } = setup();
    const resume = store.stallNextLoad();
    const slowPageLoad = inventory.availability("tour-oslo"); // has read floor: 4 and is waiting
    await inventory.reserve("tour-oslo", "floor", 4);
    resume();
    await slowPageLoad;
    const shown = await inventory.availability("tour-oslo");
    console.log("availability after the floor sold out:", shown);
    assert.equal(shown.floor, 0);
});

test("released seats can be bought even if a page was loading during the release", async () => {
    const { store, inventory } = setup();
    const resume = store.stallNextLoad();
    const slowPageLoad = inventory.availability("tour-oslo"); // has read balcony: 0
    await inventory.release("tour-oslo", "balcony", 2);
    resume();
    await slowPageLoad;
    assert.deepEqual(await holdSeats(inventory, "tour-oslo", "balcony", 2), { ok: true, section: "balcony", qty: 2 });
});

test("an older read never replaces a newer cached count", async () => {
    const { store, inventory } = setup();
    const resume = store.stallNextLoad();
    const slow = inventory.availability("tour-oslo");
    await inventory.reserve("tour-oslo", "floor", 1);
    assert.equal((await inventory.availability("tour-oslo")).floor, 3); // a fresh read caches version 2
    resume();
    await slow;
    assert.equal((await inventory.availability("tour-oslo")).floor, 3);
});

test("holds are refused when the section is sold out or the order is too big", async () => {
    const { inventory } = setup();
    assert.deepEqual(await holdSeats(inventory, "tour-oslo", "floor", 9), { ok: false, reason: "too_many" });
    await holdSeats(inventory, "tour-oslo", "floor", 3);
    assert.deepEqual(await holdSeats(inventory, "tour-oslo", "floor", 2), { ok: false, reason: "sold_out" });
    assert.equal((await inventory.availability("tour-oslo")).floor, 1);
});

test("cached availability expires after the TTL", async () => {
    const { store, inventory, advance } = setup();
    await inventory.availability("tour-oslo");
    advance(AVAILABILITY_TTL_MS);
    await inventory.availability("tour-oslo");
    assert.equal(store.loads, 2);
});
